def transform(grid):
    g = np.array(grid)
    bg = background(g)
    col_of = {5: 0, 2: 1, 8: 2, 9: 3, 6: 4}
    counts = {}
    for c in np.unique(g):
        c = int(c)
        if c == bg:
            continue
        counts[c] = len(components(g == c, diagonal=True))
    H = max(counts.values())
    out = np.full((H, 5), bg, dtype=int)
    emit(out, f"Allocate a {H}x5 background canvas; height = largest number of diagonally-connected objects of any colour.")
    for c in sorted(counts, key=lambda k: col_of.get(k, 99)):
        if c not in col_of:
            continue
        x = col_of[c]
        n = counts[c]
        out[H - n:, x] = c
        emit(out, f"Colour {c} has {n} diagonally-connected object(s): draw a bar of height {n} at the bottom of its legend column {x}.")
    emit(out, "Final bar chart.")
    return out
